    for panel_color, motif_color, top, left in panels:
        tile = [[panel_color] * 8 for _ in range(8)]
        for r in range(6):
            for c in range(6):
                if grid[top + r][left + c] == motif_color:
                    tile[r + 1][c + 1] = motif_color
        tiles.append(tile)

    result = []
    for start in (0, 2):
        for r in range(8):
            result.append(tiles[start][r] + tiles[start + 1][r])
    return result
